import{_ as s,a0 as i,w as l,s as g,I as t,x as e,a1 as n,A as a,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"惠普買了 WebOS 的麪包，谷歌僱了 WebOS 的烘焙師——安卓設計革命的起點 | LCTT x X-CMD","titleTemplate":false,"description":"2011 年安卓 3.0 蜂巢發佈，Matias Duarte 從 Palm 跳到谷歌後第一次掌舵安卓設計。Xoom 平板、急切發佈的科幻主題、閉源決策——安卓設計革命的起點。15 年後看，蜂巢看似失敗，但它埋下的\\"軟件導航鍵 + 多任務卡片 + 系統級 UI 主管\\"三件套，今天統治所有移動 OS。","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"惠普買了 WebOS 的麪包，谷歌僱了 WebOS 的烘焙師——安卓設計革命的起點 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2011 年安卓 3.0 蜂巢發佈，Matias Duarte 從 Palm 跳到谷歌後第一次掌舵安卓設計。Xoom 平板、急切發佈的科幻主題、閉源決策——安卓設計革命的起點。15 年後看，蜂巢看似失敗，但它埋下的\\"軟件導航鍵 + 多任務卡片 + 系統級 UI 主管\\"三件套，今天統治所有移動 OS。"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/16 - The history of Android.digest","title":"惠普買了 WebOS 的麪包，谷歌僱了 WebOS 的烘焙師——安卓設計革命的起點","tag":"The history of Android","desc":"2011 年安卓 3.0 蜂巢發佈，Matias Duarte 從 Palm 跳到谷歌後第一次掌舵安卓設計。Xoom 平板、急切發佈的科幻主題、閉源決策——安卓設計革命的起點。15 年後看，蜂巢看似失敗，但它埋下的\\"軟件導航鍵 + 多任務卡片 + 系統級 UI 主管\\"三件套，今天統治所有移動 OS。"},"relativePath":"The history of Android/16 - The history of Android.digest.md","filePath":"[post].md"}'),d={name:"The history of Android/16 - The history of Android.digest.md"};function p(h,o,m,S,q,O){const r=i("Link");return l(),g("div",null,[o[13]||(o[13]=t("h1",{id:"惠普買了-webos-的麪包-谷歌僱了-webos-的烘焙師——安卓設計革命的起點",tabindex:"-1"},[e("惠普買了 WebOS 的麪包，谷歌僱了 WebOS 的烘焙師——安卓設計革命的起點 "),t("a",{class:"header-anchor",href:"#惠普買了-webos-的麪包-谷歌僱了-webos-的烘焙師——安卓設計革命的起點","aria-label":"Permalink to “惠普買了 WebOS 的麪包，谷歌僱了 WebOS 的烘焙師——安卓設計革命的起點”"},"​")],-1)),t("blockquote",null,[t("p",null,[o[1]||(o[1]=e("老文新評 #009 · ",-1)),n(r,{href:"https://lctt.x-cmd.com/The%20history%20of%20Android/16%20-%20The%20history%20of%20Android/",rel:"nofollow noopener"},{default:a(()=>[...o[0]||(o[0]=[e("lctt.x-cmd.com",-1)])]),_:1}),o[2]||(o[2]=e(" · 2014-01-01",-1))])]),o[14]||(o[14]=u('<p>2010 年 4 月，惠普花 10 億美元收購 Palm，買下了 WebOS 這個&quot;擁有優秀 UI 的移動操作系統&quot;。但 WebOS 的首席設計師 Matias Duarte 沒跟着去惠普——2010 年 5 月他跳到了谷歌。一年後安卓 3.0 蜂巢發佈，被普遍認為是安卓&quot;設計復興&quot;的起點。Ron Amadeo 在編年史第十五篇裏講了一個冷笑話：<strong>惠普買下了麪包，谷歌僱走了烘焙師</strong>。</p><p>15 年後再看，蜂巢看似失敗，但它埋下的三件套今天統治所有移動 OS——Xoom 在 iPad 2 面前潰敗，半年後 Google 匆忙把代碼合併回主線，但「軟件導航鍵 + 多任務卡片 + 系統級 UI 主管」這三件套，今天 iOS / iPadOS / Vision Pro / 鴻蒙都在用。</p><h2 id="文章講了啥" tabindex="-1">文章講了啥 <a class="header-anchor" href="#文章講了啥" aria-label="Permalink to “文章講了啥”">​</a></h2><p>Ron 把這章的重點放在三個變革上：</p><ul><li><strong>設計師主政的開始</strong>：Matias Duarte 被任命為安卓用户體驗主管，第一次有人公開掌管安卓外觀。整個界面被重構：黑色背景、藍色光暈、六邊形蜂巢壁紙——科幻感十足</li><li><strong>軟件按鍵取代實體鍵</strong>：蜂巢引入系統欄，把返回/菜單/Home 全部軟件化。這意味着任何帶觸摸屏的設備都能跑安卓，不再依賴實體鍵</li><li><strong>&quot;最近應用&quot;列表的誕生</strong>：受 WebOS 卡片式多任務啓發，安卓終於有了可視化的任務切換——儘管初代版本不能滾動</li></ul><p>但 Ron 也批評了蜂巢的急功近利：發佈時不穩、SD 卡不工作、Flash 不支持、源碼不開源。這一切都是因為谷歌不想讓手機社區拿&quot;半生不熟的蜂巢&quot;做移植。</p><h2 id="_15-年後重讀" tabindex="-1">15 年後重讀 <a class="header-anchor" href="#_15-年後重讀" aria-label="Permalink to “15 年後重讀”">​</a></h2><h3 id="這些觀點今天還成立嗎" tabindex="-1">這些觀點今天還成立嗎？ <a class="header-anchor" href="#這些觀點今天還成立嗎" aria-label="Permalink to “這些觀點今天還成立嗎？”">​</a></h3><ul><li>✅ <strong>軟件按鍵能取代實體鍵</strong> —— 早已普及，全面屏更進一步</li><li>✅ <strong>Matias Duarte 主管安卓設計</strong> —— 之後他主導 Material Design</li><li>✅ <strong>WebOS 卡片式多任務是好的設計</strong> —— 現代安卓/iOS 都借鑑了</li><li>✅ <strong>蜂巢科幻主題需要淡化</strong> —— 後續版本確實在淡化</li><li>⚠️ <strong>不開源平板源碼是正確選擇</strong> —— 後來谷歌放棄了這個策略</li><li>❌ <strong>平板需要獨立於手機的系統</strong> —— 後來的 ChromeOS/iPadOS 反而做了融合</li></ul><h3 id="三件安卓設計遺產-今天統治所有移動-os" tabindex="-1">三件安卓設計遺產，今天統治所有移動 OS <a class="header-anchor" href="#三件安卓設計遺產-今天統治所有移動-os" aria-label="Permalink to “三件安卓設計遺產，今天統治所有移動 OS”">​</a></h3><p>15 年後回看，蜂巢看似失敗，但它埋下的三件套今天統治所有移動 OS：</p><p><strong>第一件：軟件導航鍵</strong>。蜂巢被批評的&quot;屏幕底部黑條&quot;後來被證明是遠見——所有全面屏手機的實現都依賴這套邏輯。Apple 從 iPhone X（2017）開始也切到軟件導航鍵，本質是同一邏輯。</p><p><strong>第二件：卡片式多任務</strong>。WebOS 的卡片式任務管理被 Duarte 複製到安卓 3.0，今天 iOS / iPadOS / Vision Pro 的多任務設計都帶着這套基因——Android 至今的&quot;最近應用&quot;和 iOS 的 App Switcher 同源。</p><p><strong>第三件：系統級 UI 主管</strong>。Duarte 是安卓史上第一個&quot;公開管設計&quot;的人。在他之前沒人覺得安卓需要&quot;設計 VP&quot;——微軟、蘋果也都沒有這個崗位。蜂巢之後，<strong>Google 設了 Material Design 部門、蘋果設了 Human Interface 部門、華為設了 EMUI 設計部</strong>——這個組織架構本身就是 Duarte 影響的延續。</p><h3 id="蜂巢閉源-14-個月-安卓社區炸鍋——但實際推動了安卓模組化" tabindex="-1">蜂巢閉源 14 個月，安卓社區炸鍋——但實際推動了安卓模組化 <a class="header-anchor" href="#蜂巢閉源-14-個月-安卓社區炸鍋——但實際推動了安卓模組化" aria-label="Permalink to “蜂巢閉源 14 個月，安卓社區炸鍋——但實際推動了安卓模組化”">​</a></h3><p>2011 年蜂巢源碼不開源這件事，<strong>Ron 當年把它講成 Google 的&quot;傲慢決策&quot;</strong>——安卓一直開源，憑什麼這次不開。</p><p>15 年後回看，<strong>閉源決策反而意外推動了 Project Treble 和 GKI 的誕生</strong>。</p><p>Google 當年閉源的理由是&quot;不想讓手機社區拿半生不熟的蜂巢做移植&quot;——這個邏輯的本質是&quot;模組化尚未成熟，源碼開放會失控&quot;。結果就是 Google 在閉源期間被迫做出更乾淨的模組邊界——HAL 層、Vendor 接口、System 層開始解耦。</p><p><strong>開放源碼的代價是混亂，閉源的代價是被罵，但回報是模組化</strong>。Google 選了&quot;先模組化、再開源&quot;的路，2013 年蜂巢源碼重新開放時，已經具備主幹的兼容性。2017 年 Project Treble 上線時（Android 8.0），這種&quot;模組化先行&quot;思路成為產品策略。</p><p><strong>這是 Android 當年給整個開源世界留下的方法論</strong>：當一個項目還沒設計好邊界時，先別開源，先把模組切乾淨，再放開。</p><h3 id="平板需要獨立-os-這件事-15-年後被證明錯了" tabindex="-1">&quot;平板需要獨立 OS&quot;這件事 15 年後被證明錯了 <a class="header-anchor" href="#平板需要獨立-os-這件事-15-年後被證明錯了" aria-label="Permalink to “平板需要獨立 OS這件事 15 年後被證明錯了”">​</a></h3><p>Ron 當年特別強調蜂巢的&quot;只為平板設計&quot;——把平板當作獨立的硬件形態。這套思路跟 Surface / iPad 當年的策略一致。</p><p>15 年後回看，<strong>&quot;平板需要獨立 OS&quot;是被打臉的設計哲學</strong>。Google 在 2012-2014 年走了 2 年彎路（Android 4.0 重新把平板和手機合併為通用版本），2023 年重啓平板路線（Pixel Tablet）時直接用手機 Android 14——<strong>根本沒專屬 OS</strong>。</p><p>iPadOS 是 2019 年才從 iOS 分離的，本質是同一套內核加平板 UI。鴻蒙在 HarmonyOS NEXT 時代更是把手機、平板、電視、車機、PC 用一套內核覆蓋——徹底放棄&quot;分形態設計&quot;。</p><p><strong>這件事的教訓是 2026 年所有 OS 設計哲學都該記住的</strong>：<strong>模組化優於專門化</strong>。15 年前 Google 想給平板做專門 OS，今天所有人都用同一套系統跨設備運行。</p><p><strong>AI Agent 元年這也成立</strong>——你想給&quot;AI 平板&quot;、&quot;AI PC&quot;、&quot;AI 手機&quot;做不同的 OS 嗎？還是做一套 Agent OS 跨設備跑？<strong>所有大公司選了後者</strong>——OpenAI ChatGPT、Anthropic Claude、Google Gemini、Apple Intelligence 都是 device-agnostic 的。</p><h3 id="matias-duarte-是被嚴重低估的安卓關鍵人物" tabindex="-1">Matias Duarte 是被嚴重低估的安卓關鍵人物 <a class="header-anchor" href="#matias-duarte-是被嚴重低估的安卓關鍵人物" aria-label="Permalink to “Matias Duarte 是被嚴重低估的安卓關鍵人物”">​</a></h3><p>蜂巢這一篇最有價值的不是技術，是<strong>Ron Amadeo 讓讀者認識 Matias Duarte 這個人</strong>。</p><p>Duarte 在 Palm 設計 WebOS 時已經做出&quot;卡片式多任務&quot;、&quot;手勢驅動&quot;這些影響一代的設計。他 2010 年跳到 Google 時帶的不是單個項目，是<strong>一整套設計哲學</strong>。15 年後 Google 的 Material Design、Pixel UI、ChromeOS 系統級 UI、Gemini 交互範式，都跟 Duarte 當年那一跳有直接關係。</p><p><strong>Duarte 是 Pixels Pixel、Material Design 的真正締造者</strong>——但他的名字在科技媒體上遠不如 Steve Jobs / Jony Ive 知名。<strong>這是開源/消費 OS 設計師的真實處境</strong>：你做出革命性 UI，但沒人記住你。</p><p>AI Agent 元年的今天，這種&quot;無名設計師&quot;的傳統仍在延續——Anthropic 的 Amanda Askell、OpenAI 的 Christine Payne、Google 的 Noam Shazeer，他們設計的產品每天影響 10 億人，但沒人知道他們的名字。</p><h3 id="最尷尬也最重要的版本" tabindex="-1">最尷尬也最重要的版本 <a class="header-anchor" href="#最尷尬也最重要的版本" aria-label="Permalink to “最尷尬也最重要的版本”">​</a></h3><p>蜂巢是安卓史上最尷尬但最重要的版本之一。<strong>它的失敗讓 Google 學會了兩個事</strong>：</p><p>第一，<strong>模組化優先於開放</strong>——源碼可以不開，但模組邊界必須切乾淨 第二，<strong>跨形態優於專屬形態</strong>——平板不需要專屬 OS，平板需要&quot;通用 OS 的平板模式&quot;</p><p><strong>這兩件事 15 年後成為所有 OS 設計的基礎共識</strong>。Linux 內核、鴻蒙 NEXT、ChromeOS、Fuchsia 都在用這套思路。</p><p>AI Agent 元年的今天，&quot;蜂巢式失敗&quot;仍然在上演——<strong>Vision Pro 2、Rabbit R1、Humane AI Pin，都是&quot;先做專屬硬件 + 專屬 OS + 專屬 AI&quot;</strong>。2026 年看，它們都活不過 3 年。蜂巢當年留下的教訓是：先把通用 OS 做對，再考慮專屬硬件。</p><hr><p><strong>出處</strong></p>',38)),t("ul",null,[t("li",null,[o[4]||(o[4]=t("strong",null,"原文",-1)),o[5]||(o[5]=e("（ARR 風險）：",-1)),n(r,{href:"http://arstechnica.com/gadgets/2011/03/ars-reviews-the-motorola-xoom/",rel:"nofollow noopener"},{default:a(()=>[...o[3]||(o[3]=[e("arstechnica.com",-1)])]),_:1})]),t("li",null,[o[7]||(o[7]=t("strong",null,"LCTT 譯稿源檔",-1)),o[8]||(o[8]=e("：",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject/blob/master/sources/tech/20140101%20%E5%AE%89%E5%8D%93%E7%BC%96%E5%B9%B4%E5%8F%B2%EF%BC%8816%EF%BC%89.md"},{default:a(()=>[...o[6]||(o[6]=[e("github.com/LCTT/TranslateProject",-1)])]),_:1})]),t("li",null,[o[10]||(o[10]=t("strong",null,"原譯",-1)),o[11]||(o[11]=e("：",-1)),n(r,{href:"https://lctt.x-cmd.com/The%20history%20of%20Android/16%20-%20The%20history%20of%20Android/"},{default:a(()=>[...o[9]||(o[9]=[e("lctt.x-cmd.com",-1)])]),_:1})]),o[12]||(o[12]=t("li",null,[t("strong",null,"發佈"),e("：2014-01-01")],-1))]),o[15]||(o[15]=t("hr",null,null,-1))])}const P=s(d,[["render",p]]);export{f as __pageData,P as default};
